void Solver::rephase() {
    rephases = 0;
    threshold *= 0.85;
    rephase_limit += 10240;

    // Update saved phases based on current trail and local best
    int phase_rand = rand() % 100;
    if (phase_rand < 60) {
        // Use local best phase (most frequent recent assignments)
        for (int i = 1; i <= vars; i++) saved[i] = local_best[i];
    } else if (phase_rand < 70) {
        // Invert local best phase
        for (int i = 1; i <= vars; i++) saved[i] = -local_best[i];
    } else if (phase_rand < 85) {
        // Random phase
        for (int i = 1; i <= vars; i++) saved[i] = rand() % 2 ? 1 : -1;
    } else {
        // Clear phase (use VSIDS default)
        for (int i = 1; i <= vars; i++) saved[i] = 0;
    }
}
